# used to generate error codes in src/error_codes.jl
# if run with no args, prints the generated code to stdout
# with a file argument, write the code to that file
# e.g., julia deps/error_codes.jl src/error_codes.jl
#
# only needs to be re-run if the Travis diff job fails

using EzXML
using HTTP
using OrderedCollections


# Keep in sync with CI: generate the union of the oldest supported PostgreSQL
# version and the newest one, since SQLSTATE codes are mostly additive.
const POSTGRESQL_ERROR_CODE_VERSIONS = (14, 18)
const ERROR_CODE_APPENDICES = Tuple(
    "https://www.postgresql.org/docs/$v/errcodes-appendix.html"
    for v in POSTGRESQL_ERROR_CODE_VERSIONS
)
const HEADER = "# Autogenerated by deps/error_codes.jl using https://www.postgresql.org/docs/{version}/errcodes-appendix.html.\n# This file covers codes for versions v$(POSTGRESQL_ERROR_CODE_VERSIONS[1]) to v$(POSTGRESQL_ERROR_CODE_VERSIONS[end])"

const SUCCESS_CLASS = "C00"
const WARNING_CLASSES = ("C01", "C02")
const EXTERNAL_CLASSES = ("C38", "C39")


pascalcase(str) = replace(titlecase(str), '_' => "")

error_code_html(url) = String(HTTP.get(url))

function error_code_table(html)
    parsed = parsehtml(html)

    return findfirst("//table[@summary='PostgreSQL Error Codes']", parsed)
end

parse_row(node) = map(nodecontent, findall("td/code", node))

# Returns the error code rows for a given URL as an OrderedDict to minimize churn
function error_code_rows(url)
    html = error_code_html(url)
    table = error_code_table(html)
    rows = findall("tbody/tr/td/code/../..", table)
    return OrderedDict(Pair(parse_row(row)...) for row in rows)
end

# Merge the error code rows from multiple URLs into a single OrderedDict
# NOTE: This will use the order from the earliest support Postgres version and warn if a code is renamed.
function merge_error_codes(urls=ERROR_CODE_APPENDICES)
    return mergewith(error_code_rows.(urls)...) do a, b
        a == b || @warn "Error code was renamed between PostgreSQL versions" old=a new=b
        return b
    end
end

function generate_error_codes(io, codes=merge_error_codes())
    id_names = Set{String}()

    class_enum_io = IOBuffer()
    println(class_enum_io, "@cenum(\n    # Enum type\n    Class,\n    # Enum values")
    error_enum_io = IOBuffer()
    println(error_enum_io, "@cenum(\n    # Enum type\n    ErrorCode,\n    # Enum values")
    alias_io = IOBuffer()
    error_names_io = IOBuffer()
    println(error_names_io, "const ERROR_NAMES = Dict(")
    classes = Set{String}()

    for (code, name) in codes
        id_name = pascalcase(name)
        class = "C$(code[1:2])"
        error_code = "E$code"

        # Not every class has a placeholder "000" code (e.g. Class 10, XQuery Error), so
        # register each class the first time any of its codes appears.
        class in classes || (push!(classes, class); println(class_enum_io, "    $class,"))

        if endswith(code, "000")
            suffix = class in (SUCCESS_CLASS, WARNING_CLASSES...) ? "Class" : "ErrorClass"
            println(
                alias_io,
                "\n# $id_name\nconst $(id_name)$(suffix) = PQResultError{$class}\n",
            )
        end

        if class in WARNING_CLASSES
            id_name *= "Warning"
        end

        if id_name in id_names
            if class in EXTERNAL_CLASSES
                id_name *= "Ext"  # like psycopg2
            else
                error("Duplicate identifier: $id_name")
            end
        end

        push!(id_names, id_name)

        println(alias_io, "const $(id_name) = PQResultError{$class,$error_code}")
        println(error_enum_io, "    $error_code,")
        println(error_names_io, "    $id_name => \"$id_name\",")
    end

    # unknown error
    class = "CUN"
    error_code = "EUNOWN"
    println(class_enum_io, "    $class,")
    println(
        alias_io, "\n# Unknown Error\nconst UnknownErrorClass = PQResultError{$class}\n"
    )
    println(alias_io, "const UnknownError = PQResultError{$class,$error_code}")
    println(error_enum_io, "    $error_code,")
    println(error_names_io, "    UnknownError => \"UnknownError\",")

    println(class_enum_io, ")")
    println(error_enum_io, ")")
    println(error_names_io, ")")

    foreach(seekstart, (class_enum_io, error_enum_io, alias_io, error_names_io))
    write(
        io,
        HEADER,
        "\n\n",
        class_enum_io,
        "\n",
        error_enum_io,
        alias_io,
        "\n",
        error_names_io,
    )

    return
end

function main()
    if length(ARGS) > 0
        open(ARGS[1], "w") do fp
            generate_error_codes(fp)
        end
    else
        generate_error_codes(stdout)
    end
end

abspath(PROGRAM_FILE) == @__FILE__() && main()
